'use strict';var IssuesModule=(function(){var CURRENT_STATUS='aberto';var CURRENT_Q='';var SEARCH_TIMER=null;function init(){loadIssues()}
function setFilter(status){CURRENT_STATUS=status;var tabs=document.querySelectorAll('#issueStatusTabs button');tabs.forEach(function(btn){var s=btn.getAttribute('data-status');btn.classList.toggle('active-tab',s===status)});loadIssues()}
function onSearchInput(){clearTimeout(SEARCH_TIMER);SEARCH_TIMER=setTimeout(function(){var input=document.getElementById('txtIssueSearch');CURRENT_Q=input?input.value.trim():'';loadIssues()},300)}
function loadIssues(){var container=document.getElementById('issuesContainer');if(!container)return;var url='/api/issues?status='+encodeURIComponent(CURRENT_STATUS)+'&q='+encodeURIComponent(CURRENT_Q);api('GET',url).then(function(res){updateStats(res.stats||{});renderIssues(res.issues||[])}).catch(function(err){container.innerHTML='<div style="padding:2rem;text-align:center;color:var(--danger);background:var(--docs-surface);border:1px solid var(--docs-border);border-radius:12px;">'+(err.message||'Erro ao carregar lista de issues.')+'</div>'})}
function formatDate(d){if(!d)return'—';try{var date=new Date(d.replace(' ','T'));if(isNaN(date.getTime()))return d;return date.toLocaleDateString('pt-BR',{day:'2-digit',month:'2-digit',year:'numeric'})+' '+date.toLocaleTimeString('pt-BR',{hour:'2-digit',minute:'2-digit'})}catch(e){return d}}
function updateStats(stats){var elAbertas=document.getElementById('statAbertas');var elAguardando=document.getElementById('statAguardando');var elConcluidas=document.getElementById('statConcluidas');var elTotal=document.getElementById('statTotal');if(elAbertas)elAbertas.textContent=stats.abertas||0;if(elAguardando)elAguardando.textContent=stats.aguardando_aprovacao||0;if(elConcluidas)elConcluidas.textContent=stats.concluidas||0;if(elTotal)elTotal.textContent=stats.total||0;var sidebarBadge=document.getElementById('sidebarIssuesBadge');if(sidebarBadge){var abertas=typeof stats.abertas!=='undefined'?(stats.abertas||0):0;if(abertas>0){sidebarBadge.textContent=abertas;sidebarBadge.hidden=!1}else{sidebarBadge.hidden=!0}}}
function renderIssues(issues){var container=document.getElementById('issuesContainer');if(!container)return;if(!issues||issues.length===0){container.innerHTML='<div style="padding:3rem;text-align:center;color:var(--docs-text-mut);background:var(--docs-surface);border:1px dashed var(--docs-border);border-radius:12px;font-size:0.9rem;">'+'Nenhuma issue encontrada para os filtros selecionados.'+'</div>';return}
var html='';issues.forEach(function(c){var status=c.status||'aberto';var isLocked=c.is_locked||status==='concluido';var statusBadge='';var statusBgStyle='';if(status==='concluido'){var lockIcon=(window.Icons&&typeof window.Icons.get==='function')?window.Icons.get('lock',{size:14}):'🔒';statusBgStyle='border-color: rgba(34, 197, 94, 0.3); background: rgba(34, 197, 94, 0.03);';statusBadge='<span style="font-size:0.75rem;padding:3px 10px;border-radius:6px;background:rgba(34,197,94,0.15);color:#16a34a;font-weight:700;display:inline-flex;align-items:center;gap:4px;">'+lockIcon+' Concluída & Travada</span>'}else if(status==='resolvido_pendente'){statusBgStyle='border-color: rgba(234, 179, 8, 0.35); background: rgba(234, 179, 8, 0.03);';statusBadge='<span style="font-size:0.75rem;padding:3px 10px;border-radius:6px;background:rgba(234,179,8,0.15);color:#ca8a04;font-weight:700;display:inline-flex;align-items:center;gap:4px;">⏱️ Resolvido (Aguardando Aprovação)</span>'}else{statusBadge='<span style="font-size:0.75rem;padding:3px 10px;border-radius:6px;background:rgba(59,130,246,0.12);color:#2563eb;font-weight:700;display:inline-flex;align-items:center;gap:4px;">💬 Issue Aberta</span>'}
var roleBadge='';if(c.user_role==='Admin'){roleBadge='<span style="font-size:0.65rem;padding:1px 6px;border-radius:4px;background:rgba(239,68,68,0.1);color:#ef4444;font-weight:600;">Admin</span>'}else if(c.user_role==='Aprovador'){roleBadge='<span style="font-size:0.65rem;padding:1px 6px;border-radius:4px;background:rgba(245,158,11,0.1);color:#f59e0b;font-weight:600;">Aprovador</span>'}
var isSystemComment=(c.comment||'').indexOf('[Rejeição]')===0;var commentDisplay=isSystemComment?'<div style="font-size:0.88rem;color:var(--red);line-height:1.5;white-space:pre-wrap;font-style:italic;margin:0.5rem 0;">'+esc(c.comment)+'</div>':'<div style="font-size:0.92rem;color:var(--docs-text);line-height:1.5;white-space:pre-wrap;margin:0.5rem 0;">'+esc(c.comment)+'</div>';var actionsBtns='';if(c.can_resolve){actionsBtns+='<button type="button" class="btn btn-sm btn-outline-primary" onclick="IssuesModule.resolveIssue('+c.id+')" style="font-size:0.75rem;padding:4px 10px;font-weight:600;">✓ Marcar como Resolvido</button>'}
if(c.can_approve){actionsBtns+='<button type="button" onclick="IssuesModule.approveIssue('+c.id+')" style="font-size:0.75rem;padding:4px 10px;font-weight:700;background:var(--success, #22c55e);color:#fff;border:none;border-radius:6px;cursor:pointer;">✓ Aprovar Resolução (Concluir & Travar)</button>'}
if(c.can_reopen){actionsBtns+='<button type="button" onclick="IssuesModule.reopenIssue('+c.id+')" style="background:none;border:1px solid var(--docs-border);padding:4px 10px;border-radius:6px;color:var(--docs-text);font-size:0.75rem;cursor:pointer;font-weight:600;">↩ Reabrir / Recusar</button>'}
if(c.can_delete){actionsBtns+='<button type="button" onclick="IssuesModule.deleteIssue('+c.id+')" style="background:none;border:none;color:var(--red);font-size:0.75rem;cursor:pointer;font-weight:600;margin-left:4px;" title="Excluir Issue">Excluir</button>'}
var viewDocBtn='<a href="/docs/view/'+c.document_id+'#comment-'+c.id+'" class="btn btn-sm btn-outline" style="font-size:0.75rem;padding:4px 10px;font-weight:600;display:inline-flex;align-items:center;gap:4px;">'+'Ver Documento ➔'+'</a>';var metadataDetails='';if(c.resolved_by_name){metadataDetails+='<div style="font-size:0.75rem;color:var(--docs-text-mut);margin-top:6px;">Corrigido/Resolvido por <strong>'+esc(c.resolved_by_name)+'</strong>'+(c.approved_by_name?' • Aprovado e concluído por <strong>'+esc(c.approved_by_name)+'</strong>':'')+'</div>'}
var docTitle=c.doc_title?esc(c.doc_title):('Documento #'+c.document_id);var initials=(c.user_name||'U').charAt(0).toUpperCase();html+='<div id="issue-item-'+c.id+'" style="padding:1.25rem;background:var(--docs-surface, #ffffff);border:1px solid var(--docs-border, #e2e8f0);border-radius:12px;'+statusBgStyle+'">'+'<div style="display:flex;align-items:center;justify-content:space-between;margin-bottom:0.75rem;flex-wrap:wrap;gap:0.5rem;border-bottom:1px solid var(--docs-border);padding-bottom:0.6rem;">'+'<div style="display:flex;align-items:center;gap:0.5rem;">'+'<span style="font-size:0.75rem;font-weight:700;color:var(--docs-text-mut);text-transform:uppercase;">Documento:</span>'+'<a href="/docs/view/'+c.document_id+'" style="font-weight:700;font-size:0.95rem;color:var(--primary, #2563eb);text-decoration:none;">'+docTitle+'</a>'+'</div>'+statusBadge+'</div>'+'<div style="display:flex;align-items:center;justify-content:space-between;margin-bottom:0.5rem;flex-wrap:wrap;gap:0.5rem;">'+'<div style="display:flex;align-items:center;gap:0.6rem;">'+'<div style="width:32px;height:32px;border-radius:50%;background:var(--primary);color:#fff;font-weight:700;font-size:0.8rem;display:flex;align-items:center;justify-content:center;">'+esc(initials)+'</div>'+'<div>'+'<div style="font-weight:600;font-size:0.88rem;color:var(--docs-text);">'+esc(c.user_name)+' <span style="font-weight:normal;font-size:0.75rem;color:var(--docs-text-mut);">(@'+esc(c.user_login)+')</span> '+roleBadge+'</div>'+'<div style="font-size:0.72rem;color:var(--docs-text-mut);">Aberto em '+formatDate(c.created_at)+'</div>'+'</div>'+'</div>'+'</div>'+commentDisplay+metadataDetails+'<div style="display:flex;align-items:center;justify-content:space-between;margin-top:0.85rem;padding-top:0.6rem;border-top:1px solid rgba(0,0,0,0.05);flex-wrap:wrap;gap:0.5rem;">'+'<div>'+viewDocBtn+'</div>'+'<div style="display:flex;align-items:center;gap:0.5rem;">'+actionsBtns+'</div>'+'</div>'+'</div>'});container.innerHTML=html}
function resolveIssue(commentId){api('POST','/api/comments/'+commentId+'/resolve',{}).then(function(){toast('Issue marcada como resolvida! O criador foi notificado para aprovação.','info');loadIssues()}).catch(function(err){toast(err.message||'Erro ao alterar status da issue.','error')})}
function approveIssue(commentId){api('POST','/api/comments/'+commentId+'/approve',{}).then(function(){toast('Resolução aprovada! A Issue foi concluída e travada.','success');loadIssues()}).catch(function(err){toast(err.message||'Erro ao aprovar resolução.','error')})}
function reopenIssue(commentId){api('POST','/api/comments/'+commentId+'/reopen',{}).then(function(){toast('Issue reaberta para correções.','info');loadIssues()}).catch(function(err){toast(err.message||'Erro ao reabrir issue.','error')})}
function deleteIssue(commentId){showConfirm({title:'Excluir Issue?',message:'Esta ação removerá o apontamento e não poderá ser desfeita.',confirmText:'Excluir',confirmClass:'btn btn-danger'},function(){api('DELETE','/api/comments/'+commentId).then(function(){toast('Issue excluída com sucesso.','info');loadIssues()}).catch(function(err){toast(err.message||'Erro ao excluir issue.','error')})})}
return{init:init,setFilter:setFilter,onSearchInput:onSearchInput,resolveIssue:resolveIssue,approveIssue:approveIssue,reopenIssue:reopenIssue,deleteIssue:deleteIssue}})();document.addEventListener('DOMContentLoaded',IssuesModule.init)